using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using RandomNumbersApi.Data;using RandomNumbersApi.Models;namespace RandomNumbersApi.Services{public class ItemService : IItemService{private readonly ApplicationDbContext _db;private readonly ILogger<ItemService> _logger;public ItemService(ApplicationDbContext db, ILogger<ItemService> logger){_db = db;_logger = logger;}public async Task<List<Item>> GetAllAsync(CancellationToken cancellationToken = default){return await _db.Items.AsNoTracking().OrderByDescending(i => i.CreatedAt).ToListAsync(cancellationToken);}public async Task<Item?> GetByIdAsync(int id, CancellationToken cancellationToken = default){return await _db.Items.AsNoTracking().FirstOrDefaultAsync(i => i.Id == id, cancellationToken);}public async Task<Item> CreateAsync(Item item, CancellationToken cancellationToken = default){_db.Items.Add(item);await _db.SaveChangesAsync(cancellationToken);_logger.LogInformation("Created item with id {Id}", item.Id);return item;}public async Task<bool> UpdateAsync(int id, Item updated, CancellationToken cancellationToken = default){var existing = await _db.Items.FirstOrDefaultAsync(i => i.Id == id, cancellationToken);if(existing == null){return false;}existing.Name = updated.Name;await _db.SaveChangesAsync(cancellationToken);_logger.LogInformation("Updated item with id {Id}", id);return true;}public async Task<bool> DeleteAsync(int id, CancellationToken cancellationToken = default){var existing = await _db.Items.FirstOrDefaultAsync(i => i.Id == id, cancellationToken);if(existing == null){return false;}_db.Items.Remove(existing);await _db.SaveChangesAsync(cancellationToken);_logger.LogInformation("Deleted item with id {Id}", id);return true;}}}